// Budget Page
// Dedicated page for budget management and tracking

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import BudgetForm from '../components/BudgetForm';
import BudgetStatus from '../components/BudgetStatus';
import './BudgetPage.css';

function BudgetPage() {
  const [budget, setBudget] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchBudgetAndTransactions();
  }, []);

  const fetchBudgetAndTransactions = async () => {
    try {
      setLoading(true);
      
      // Fetch budget
      try {
        const budgetResponse = await axios.get('http://localhost:5000/api/budget/get', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setBudget(budgetResponse.data);
      } catch (error) {
        // Budget might not be set yet
        setBudget(null);
      }

      // Fetch transactions
      const transResponse = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(transResponse.data);
    } catch (error) {
      console.log('Error fetching data:', error.message);
    } finally {
      setLoading(false);
    }
  };

  // Calculate current month spending
  const getCurrentMonthSpending = () => {
    const now = new Date();
    const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    
    return transactions
      .filter(t => {
        const transDate = new Date(t.date);
        const transMonth = `${transDate.getFullYear()}-${String(transDate.getMonth() + 1).padStart(2, '0')}`;
        return t.type === 'expense' && transMonth === currentMonth;
      })
      .reduce((sum, t) => sum + parseFloat(t.amount), 0);
  };

  const currentSpending = getCurrentMonthSpending();
  const budgetLimit = budget ? parseFloat(budget.monthlyLimit) : 0;
  const percentageUsed = budgetLimit > 0 ? ((currentSpending / budgetLimit) * 100).toFixed(2) : 0;
  const remaining = budgetLimit - currentSpending;
  const isOverBudget = currentSpending > budgetLimit;

  return (
    <div className="budget-page">
      <Navbar />

      {/* Header */}
      <div className="budget-header">
        <h1>💰 Budget Management</h1>
        <p>Set and track your monthly budget</p>
      </div>

      {/* Budget Status Overview */}
      {budget && (
        <div className="budget-overview">
          <div className="overview-card">
            <h3>Monthly Budget</h3>
            <p className="amount">₹ {budgetLimit.toFixed(2)}</p>
          </div>

          <div className="overview-card">
            <h3>Current Spending</h3>
            <p className={`amount ${isOverBudget ? 'over-budget' : ''}`}>
              ₹ {currentSpending.toFixed(2)}
            </p>
          </div>

          <div className="overview-card">
            <h3>Remaining</h3>
            <p className={`amount ${remaining < 0 ? 'negative' : 'positive'}`}>
              ₹ {remaining.toFixed(2)}
            </p>
          </div>

          <div className="overview-card">
            <h3>Budget Used</h3>
            <p className={`amount ${isOverBudget ? 'over-budget' : ''}`}>
              {percentageUsed}%
            </p>
          </div>
        </div>
      )}

      {/* Budget Status Component */}
      <div className="budget-status-section">
        <h2>📊 Budget Status</h2>
        <BudgetStatus />
      </div>

      {/* Budget Form Section */}
      <div className="budget-form-section">
        <h2>✏️ {budget ? 'Update Budget' : 'Set Your Budget'}</h2>
        <BudgetForm onBudgetUpdated={fetchBudgetAndTransactions} />
      </div>

      {/* Budget Tips */}
      <div className="budget-tips">
        <h2>💡 Budget Tips</h2>
        <div className="tips-grid">
          <div className="tip-card">
            <div className="tip-icon">📋</div>
            <h3>Track Everything</h3>
            <p>Record all your expenses to get accurate budget tracking</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">🎯</div>
            <h3>Set Realistic Goals</h3>
            <p>Set a budget that matches your income and lifestyle</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">📊</div>
            <h3>Review Monthly</h3>
            <p>Check your spending every month and adjust as needed</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">💰</div>
            <h3>Save the Difference</h3>
            <p>Save any money left after staying within budget</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">🚨</div>
            <h3>Alert System</h3>
            <p>Get email alerts when you exceed your budget</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">📈</div>
            <h3>Increase Savings</h3>
            <p>Gradually increase your savings rate each month</p>
          </div>
        </div>
      </div>

      {/* Spending Breakdown */}
      {transactions.length > 0 && (
        <div className="spending-breakdown">
          <h2>📈 Spending Breakdown</h2>
          <div className="breakdown-content">
            <div className="breakdown-stat">
              <span>Total Transactions</span>
              <strong>{transactions.length}</strong>
            </div>
            <div className="breakdown-stat">
              <span>Income Transactions</span>
              <strong>{transactions.filter(t => t.type === 'income').length}</strong>
            </div>
            <div className="breakdown-stat">
              <span>Expense Transactions</span>
              <strong>{transactions.filter(t => t.type === 'expense').length}</strong>
            </div>
            <div className="breakdown-stat">
              <span>Total Income</span>
              <strong>
                ₹ {transactions
                  .filter(t => t.type === 'income')
                  .reduce((sum, t) => sum + parseFloat(t.amount), 0)
                  .toFixed(2)}
              </strong>
            </div>
            <div className="breakdown-stat">
              <span>Total Expenses</span>
              <strong>
                ₹ {transactions
                  .filter(t => t.type === 'expense')
                  .reduce((sum, t) => sum + parseFloat(t.amount), 0)
                  .toFixed(2)}
              </strong>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default BudgetPage;
